import (
	"fmt"
)

resp, err := client.ShoppingCartSettings().GetShoppingCart(ctx, nil, nil)
if err != nil {
	log.Fatal(err)
}
settings := resp.Map().(map[string]any)["shopping_cart"].(map[string]any)
cartPage := settings["cart_page"].(map[string]any)
flyingCart := settings["flying_cart"].(map[string]any)
fmt.Println(cartPage["show_product_thumbnail"], cartPage["save_cart"], flyingCart["enabled"], flyingCart["save_cart"])

